<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'
import { ticketApi } from '../../api/tickets'; import type { Ticket, TicketComment, TicketStatus } from '../../types'; import { useAuthStore } from '../../stores/auth'; import { hasAnyPermission, hasPermission } from '../../utils/permissions'; import { apiErrorMessage } from '../../utils/errors'; import { formatDate, shortId } from '../../utils/format'; import StatusPill from '../../components/StatusPill.vue'
const route=useRoute();const router=useRouter();const auth=useAuthStore();const id=route.params.id as string;const ticket=ref<Ticket|null>(null);const comments=ref<TicketComment[]>([]);const loading=ref(true);const busy=ref(false);const comment=ref('');const assigneeId=ref('')
const canComment=computed(()=>hasPermission(auth.user,'ticket.comment.public'));const canAssign=computed(()=>hasAnyPermission(auth.user,['ticket.assign.department','ticket.assign.all']));const canTransition=computed(()=>hasAnyPermission(auth.user,['ticket.transition.assigned','ticket.transition.all']))
const transitions=computed<TicketStatus[]>(()=>({OPEN:['IN_PROGRESS'],IN_PROGRESS:['OPEN','RESOLVED'],RESOLVED:['CLOSED'],CLOSED:[]}[ticket.value?.status||'CLOSED'] as TicketStatus[]))
async function load(){loading.value=true;try{const [detail,items]=await Promise.all([ticketApi.get(id),ticketApi.comments(id)]);ticket.value=detail.data;comments.value=items.data;assigneeId.value=detail.data.assigneeId||''}catch(e){ElMessage.error(apiErrorMessage(e));await router.replace('/tickets')}finally{loading.value=false}}
async function action(run:()=>Promise<{data:Ticket}>,message:string){busy.value=true;try{ticket.value=(await run()).data;ElMessage.success(message)}catch(e){ElMessage.error(apiErrorMessage(e));await load()}finally{busy.value=false}}
async function addComment(){if(!comment.value.trim()||!ticket.value)return;busy.value=true;try{await ticketApi.comment(id,comment.value.trim(),ticket.value.version);comment.value='';ElMessage.success('Comment added');await load()}catch(e){ElMessage.error(apiErrorMessage(e));await load()}finally{busy.value=false}}
onMounted(load)
</script>
<template><div v-loading="loading"><button class="back-link" @click="router.push('/tickets')">← Back to tickets</button><div v-if="ticket" class="detail-layout"><section><div class="detail-hero"><div><div class="detail-meta"><code>{{ ticket.id }}</code><StatusPill :value="ticket.priority" /></div><h2>{{ ticket.title }}</h2><p>{{ ticket.description }}</p></div><StatusPill :value="ticket.status" /></div><div class="content-card"><div class="card-heading"><div><span class="eyebrow">Conversation</span><h3>Comments</h3></div><span class="result-count">{{ comments.length }} entries</span></div><div v-if="comments.length" class="comment-list"><article v-for="item in comments" :key="item.id"><div class="comment-avatar">{{ item.authorId.slice(0,2).toUpperCase() }}</div><div><div class="comment-head"><code>{{ shortId(item.authorId) }}</code><time>{{ formatDate(item.createdAt) }}</time></div><p>{{ item.content }}</p></div></article></div><div v-else class="inline-empty">No comments yet.</div><div v-if="canComment" class="comment-form"><el-input v-model="comment" type="textarea" :rows="3" maxlength="4000" placeholder="Add an update…" /><el-button type="primary" :disabled="!comment.trim()" :loading="busy" @click="addComment">Add comment</el-button></div></div></section><aside class="detail-sidebar"><section class="content-card"><span class="eyebrow">Ticket details</span><dl class="metadata-list"><div><dt>Creator</dt><dd><code>{{ shortId(ticket.creatorId) }}</code></dd></div><div><dt>Assignee</dt><dd><code>{{ shortId(ticket.assigneeId) }}</code></dd></div><div><dt>Created</dt><dd>{{ formatDate(ticket.createdAt) }}</dd></div><div><dt>Updated</dt><dd>{{ formatDate(ticket.updatedAt) }}</dd></div><div><dt>Version</dt><dd>{{ ticket.version }}</dd></div></dl></section><section v-if="canAssign||canTransition" class="content-card action-card"><span class="eyebrow">Manage ticket</span><div v-if="canAssign" class="side-action"><label>Assign support user</label><el-input v-model="assigneeId" placeholder="Support user UUID" /><el-button :loading="busy" @click="action(()=>ticketApi.assign(id,assigneeId,ticket!.version),'Ticket assigned')">Assign</el-button></div><div v-if="canTransition&&transitions.length" class="side-action"><label>Change status</label><el-button v-for="status in transitions" :key="status" :loading="busy" type="primary" plain @click="action(()=>ticketApi.transition(id,status,ticket!.version),`Moved to ${status.replaceAll('_',' ')}`)">{{ status.replaceAll('_',' ') }}</el-button></div></section></aside></div></div></template>
